import "node:module";
import { isBrowserProject, isNodeProject, createRsbuildServer } from "./6~0.js";
import { createPool, validateBrowserRunConfig, ensureTestEnvironmentDependencies, runBrowserGlobalSetupStage, runGlobalTeardown, runGlobalSetup, createTestPlanner, prepareTestEnvironmentModules, loadBrowserExecutor, shouldRunGlobalSetup } from "./2~0.js";
import { toSerializedError } from "./n~0.js";
const collectNodeTests = async ({ context, planner })=>{
    const nodeProjects = planner.getPlan().nodeProjectsToRun;
    const { nodeBuild } = planner;
    if (!nodeBuild || !planner.hasNodeTestsToRun()) return {
        list: [],
        getSourceMap: async ()=>null,
        close: async ()=>void 0
    };
    const { rsbuildInstance, setupFileState, globTestSourceEntries } = nodeBuild;
    const { getRsbuildStats, closeServer } = await createRsbuildServer({
        globTestSourceEntries,
        globalSetupFiles: setupFileState.globalSetupFiles,
        isWatchMode: false,
        inspectedConfig: {
            ...context.normalizedConfig,
            projects: nodeProjects.map((p)=>p.normalizedConfig)
        },
        setupFiles: setupFileState.setupFiles,
        rsbuildInstance,
        rootPath: context.rootPath
    });
    let pool;
    let testEnvironmentModules;
    const closeResources = async ()=>{
        try {
            await closeServer();
        } finally{
            try {
                await pool?.close();
            } finally{
                await testEnvironmentModules?.cleanup();
            }
        }
    };
    try {
        await ensureTestEnvironmentDependencies(nodeProjects, context.rootPath, {
            confirm: context.packageInstallerConfirm
        });
        testEnvironmentModules = await prepareTestEnvironmentModules({
            projects: nodeProjects,
            rootPath: context.rootPath
        });
        pool = await createPool({
            context,
            testEnvironmentModules: testEnvironmentModules.modules
        });
        const activePool = pool;
        const updateSnapshot = context.snapshotManager.options.updateSnapshot;
        const returns = await Promise.all(nodeProjects.map(async (project)=>{
            const { entries, setupEntries, globalSetupEntries, getSourceMaps, getAssetFiles, assetNames } = await getRsbuildStats({
                environmentName: project.environmentName
            });
            if (shouldRunGlobalSetup(project, entries.length, globalSetupEntries.length)) {
                const files = globalSetupEntries.flatMap((e)=>e.files);
                const assetFilesPromise = getAssetFiles(files);
                const sourceMapsPromise = getSourceMaps(files);
                const [assetFiles, sourceMaps] = await Promise.all([
                    assetFilesPromise,
                    sourceMapsPromise
                ]);
                const { success, errors } = await runGlobalSetup(context, project, {
                    globalSetupEntries,
                    assetFiles,
                    sourceMaps,
                    interopDefault: true,
                    outputModule: project.outputModule,
                    federation: project.normalizedConfig.federation
                });
                if (!success) return {
                    list: [],
                    errors,
                    assetNames,
                    getSourceMaps: ()=>null
                };
            }
            const list = await activePool.collectTests({
                entries,
                assetNames,
                setupEntries,
                getAssetFiles,
                getSourceMaps,
                project,
                updateSnapshot
            });
            return {
                list,
                getSourceMaps,
                assetNames
            };
        }));
        return {
            list: returns.flatMap((r)=>r.list),
            errors: returns.flatMap((r)=>r.errors || []),
            getSourceMap: async (name)=>{
                const resource = returns.find((r)=>r.assetNames.includes(name));
                return (await resource?.getSourceMaps([
                    name
                ]))?.[name];
            },
            close: async ()=>{
                await closeResources();
            }
        };
    } catch (error) {
        await closeResources();
        throw error;
    }
};
const prepareBrowserCollection = async ({ context, planner })=>{
    if (!planner.hasBrowserTestsToRun()) return;
    const browserProjects = planner.getBrowserProjectsToRun();
    const executor = await loadBrowserExecutor(context, browserProjects, null, planner.getExecutorRunOptions(browserProjects));
    try {
        const stage = await runBrowserGlobalSetupStage(context, browserProjects, {
            entriesCache: planner.getPlan().entriesCache
        });
        return {
            executor,
            stage
        };
    } catch (error) {
        await executor.close().catch(()=>void 0);
        throw error;
    }
};
const collectBrowserTests = async (prepared)=>{
    if (!prepared) return {
        list: [],
        close: async ()=>void 0
    };
    const { executor, stage } = prepared;
    const close = async ()=>{
        await executor.close();
    };
    if (stage.errors.length) return {
        list: [],
        errors: stage.errors.map((error)=>toSerializedError(error)),
        close
    };
    try {
        const { list } = await executor.collect({
            env: stage.env
        });
        return {
            list,
            close
        };
    } catch (error) {
        await executor.close().catch(()=>void 0);
        throw error;
    }
};
const collectTestFiles = (planner)=>{
    const { projects, entriesCache } = planner.getPlan();
    const list = projects.flatMap((project)=>Object.values(entriesCache.get(project.environmentName)?.entries ?? {}).map((testPath)=>({
                testPath,
                project: project.name,
                tests: []
            })));
    return {
        close: async ()=>void 0,
        errors: [],
        list,
        getSourceMap: async ()=>null
    };
};
const collectAllTests = async ({ context, planner })=>{
    const prepared = await prepareBrowserCollection({
        context,
        planner
    });
    const nodePromise = collectNodeTests({
        context,
        planner
    });
    const browserPromise = collectBrowserTests(prepared);
    const [nodeSettled, browserSettled] = await Promise.allSettled([
        nodePromise,
        browserPromise
    ]);
    if ('rejected' === nodeSettled.status || 'rejected' === browserSettled.status) await Promise.all([
        'fulfilled' === nodeSettled.status && nodeSettled.value.close().catch(()=>void 0),
        'fulfilled' === browserSettled.status && browserSettled.value.close().catch(()=>void 0)
    ]);
    const [nodeResult, browserResult] = await Promise.all([
        nodePromise,
        browserPromise
    ]);
    return {
        errors: [
            ...nodeResult.errors ?? [],
            ...browserResult.errors ?? []
        ],
        list: [
            ...nodeResult.list,
            ...browserResult.list
        ],
        getSourceMap: nodeResult.getSourceMap,
        close: async ()=>{
            const closePromises = [
                nodeResult.close(),
                browserResult.close()
            ];
            await Promise.allSettled(closePromises);
            await Promise.all(closePromises);
        }
    };
};
async function listTests(context, { filesOnly }) {
    const showProject = context.projects.length > 1;
    const createClose = (closeCollection)=>{
        let closePromise;
        return ()=>{
            closePromise ??= (async ()=>{
                await closeCollection();
                context.exitCode.finishCycle();
            })();
            return closePromise;
        };
    };
    if (context.relatedResolutionEmpty) return {
        list: [],
        errors: [],
        showProject,
        getSourceMap: async ()=>null,
        close: createClose(async ()=>void 0)
    };
    const browserProjects = context.projects.filter(isBrowserProject);
    const nodeProjects = context.projects.filter(isNodeProject);
    const planner = await createTestPlanner(context, {
        browserProjects,
        nodeProjects,
        isWatchMode: false
    });
    if (browserProjects.length && !planner.hasValidatedBrowserConfig() && (filesOnly || !planner.hasBrowserTestsToRun())) await validateBrowserRunConfig(context, browserProjects);
    let collected;
    try {
        collected = filesOnly ? collectTestFiles(planner) : await collectAllTests({
            context,
            planner
        });
    } catch (error) {
        await runGlobalTeardown(context);
        throw error;
    }
    const { list, close, getSourceMap, errors = [] } = collected;
    const closeCollection = async ()=>{
        try {
            await close();
        } finally{
            await runGlobalTeardown(context);
        }
    };
    const hasError = list.some((file)=>file.errors?.length) || errors.length;
    if (hasError) context.exitCode.raise(1);
    return {
        list,
        errors,
        showProject,
        getSourceMap,
        close: createClose(closeCollection)
    };
}
export { listTests };
